"""Write ``ops.pyi``, the signatures of ``srv.ops``, from the operation registry.

Each parameter's type comes from the JSON schema of the operation's model,
which is what the operation accepts from any caller: a nested model is a
dict, an enum is a Literal. ``make ops-stubs`` runs this and formats the
result; tests/test_library.py fails when the committed file differs.
"""

from __future__ import annotations

import sys
import tempfile
from pathlib import Path
from typing import Any

from .ops import attr_name

HEADER = """\
# Generated by `make ops-stubs` (src/aegis/api/stubs.py) from the operation
# registry. Do not edit: change the operation's params model and regenerate.
import builtins
from typing import Any, Literal

from ..server import Server

def attr_name(op: str) -> tuple[str, str]: ...
"""

SCALARS = {
    "string": "str",
    "integer": "int",
    "number": "float",
    "boolean": "bool",
    "null": "None",
}


def py_type(s: dict, defs: dict) -> str:
    """The Python type a JSON schema accepts."""
    if "$ref" in s:
        return py_type(defs[s["$ref"].rsplit("/", 1)[-1]], defs)
    if "const" in s:
        return f"Literal[{s['const']!r}]"
    if "enum" in s:
        return f"Literal[{', '.join(repr(v) for v in s['enum'])}]"
    for key in ("anyOf", "oneOf"):
        if key in s:
            parts: list[str] = []
            for sub in s[key]:
                t = py_type(sub, defs)
                if t not in parts:
                    parts.append(t)
            return " | ".join(parts)
    t = s.get("type")
    if isinstance(t, list):
        return " | ".join(py_type({**s, "type": x}, defs) for x in t)
    if t in SCALARS:
        return SCALARS[t]
    if t == "array":
        # builtins.list: a namespace may have an operation named list.
        return f"builtins.list[{py_type(s.get('items', {}), defs)}]"
    if t == "object":
        extra = s.get("additionalProperties")
        if isinstance(extra, dict) and extra:
            return f"dict[str, {py_type(extra, defs)}]"
        return "dict[str, Any]"
    return "Any"


def _doc(text: str) -> str:
    first = " ".join(text.split("\n\n", 1)[0].split())
    return first.replace("\\", "\\\\").replace('"""', '\\"\\"\\"')


def _method(name: str, op: Any, indent: str) -> list[str]:
    schema = op.params.model_json_schema()
    defs = schema.get("$defs", {})
    required = set(schema.get("required", []))
    args = []
    for field, sub in schema.get("properties", {}).items():
        t = py_type(sub, defs)
        args.append(f"{field}: {t}" + ("" if field in required else " = ..."))
    sig = ", ".join(["self", *(["*", *args] if args else [])])
    return [
        f"{indent}async def {name}({sig}) -> Any:",
        f'{indent}    """{_doc(op.doc) or op.name}"""',
    ]


def render(registry: Any) -> str:
    by_ns: dict[str, list[tuple[str, Any]]] = {}
    for op in registry.names():
        ns, name = attr_name(op)
        by_ns.setdefault(ns, []).append((name, registry._ops[op]))
    out = [HEADER, "class Ops:", "    def __init__(self, server: Server) -> None: ..."]
    for ns in sorted(by_ns):
        if by_ns[ns][0][0] == "":
            out += _method(ns, by_ns[ns][0][1], "    ")
        else:
            out += ["    @property", f"    def {ns}(self) -> _{ns}: ..."]
    out.append("")
    for ns in sorted(by_ns):
        if by_ns[ns][0][0] == "":
            continue
        out.append(f"class _{ns}:")
        for name, op in by_ns[ns]:
            out += _method(name, op, "    ")
        out.append("")
    return "\n".join(out)


def main() -> None:
    from ..app import App
    from ..roots import make_roots

    with tempfile.TemporaryDirectory() as d:
        root = Path(d)
        (root / ".aegis.yaml").write_text("")
        app = App(make_roots(root, None))
        sys.stdout.write(render(app.registry))


if __name__ == "__main__":
    main()
